-- Generated by tools/bundle_libs.py — do not edit by hand. Regenerate with: python3 tools/bundle_libs.py
local __LIBS = {}
local __LOADERS = {}
-- Forward declaration: libraries call require_lib at load time.
local require_lib

__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["content"] = function(...)
-- =====================================================================
-- Lib: chapter-text cleanup shared by the novel extractors.
-- Loaded via require_lib("content"). No dependencies on other libs.
--
-- Engine API used inside the functions only: string_normalize,
-- regex_replace, string_trim (all guarded, so the module still loads
-- outside the app).
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Chapter-heading prefix that gets stripped when it duplicates the
-- chapter title the engine already shows (guide:823). Language picks the
-- word for the ordinal; unknown/missing lang falls back to the dominant
-- ru/en cluster (Глава N | Chapter N).
local HEAD_BY_LANG = {
    ru = "(Глава\\s+\\d+|Chapter\\s+\\d+)",
    en = "(Chapter\\s+\\d+)",
    zh = "(第[\\d一二三四五六七八九十百]+[章节卷回部集篇]|Chapter\\s+\\d+)",
    ja = "(第\\s*\\d+話|Chapter\\s+\\d+)",
    id = "(Bab\\s+\\d+|Chapter\\s+\\d+)",
}

-- Credit lines: the English set is in every copy that has a credits
-- step at all; the per-language set is the union of the ru (ru/bookhamster,
-- ru/ifreedom, ru/jaomix), zh (zh/twkan, zh/sto9) and id (id/indowebnovel)
-- variants. Both are applied for the chosen language.
local CREDITS_EN =
    "(?im)^\\s*(Translator|Editor|Proofreader|Read\\s+(at|on|latest))[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)"

local CREDITS_BY_LANG = {
    ru = "(?im)^\\s*(Перевод|Переводчик|Редакция|Редактор|Аннотация|Сайт|Источник|Студия)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
    zh = "(?im)^\\s*(翻译|譯者|译者|編輯|编辑|校對|校对|更新|閱讀|阅读|最新閱讀|最新阅读)[:\\s：][^\\n\\r]{0,70}(\\r?\\n|$)",
    id = "(?im)^\\s*(Penerjemah|Editor|Proofreader|Baca\\s+(di|novel|lanjutan)|Sumber|Donasi|Trakteer)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
}

-- Escape regex metacharacters of a literal chapter title or domain
-- (Java/Kotlin regex syntax: backslash-escape, not %-escape).
local function escapeLiteral(s)
    return (s:gsub("[%.%+%-%*%?%[%]%(%){}%$%^%|%%]", "\\%1"))
end

-- applyStandardContentTransforms (guide:812) as a shared function.
--   opts.domain      — baseUrl (or a bare host): lines mentioning it are dropped;
--   opts.chapterTitle — literal title to strip instead of the "Глава/Chapter N"
--                      prefix (duplicates the title field of the chapter);
--   opts.lang        — "ru" (default) / "en" / "zh" / "ja" / "id": picks the
--                      chapter-heading word and the extra credit lines.
-- Returns "" for an empty input, as every copy does.
function M.standardTransforms(text, opts)
    if not text or text == "" then return "" end
    opts = opts or {}
    local lang = opts.lang or "ru"

    if type(string_normalize) == "function" then
        text = string_normalize(text)
    end

    if type(regex_replace) ~= "function" then
        logErr("meta/content: regex_replace unavailable, transforms skipped")
        return trim(text)
    end

    -- 1. lines linking back to the source site (watermarks, "read more")
    local domain = opts.domain
    if type(domain) == "string" and domain ~= "" then
        domain = domain:gsub("https?://", ""):gsub("^www%.", ""):gsub("/$", "")
        if domain ~= "" then
            text = regex_replace(text, "(?i)" .. escapeLiteral(domain) .. ".*?\\n", "")
        end
    end

    -- 2. leading chapter heading, duplicated in the title field
    local head = opts.chapterTitle
        and ("(" .. escapeLiteral(opts.chapterTitle) .. ")")
        or HEAD_BY_LANG[lang] or HEAD_BY_LANG.ru
    text = regex_replace(text, "(?i)\\A[\\s\\p{Z}\\uFEFF]*(" .. head .. "[^\\n\\r]*[\\n\\r\\s]*)+", "")

    -- 3. translator / editor / "read at" credit lines
    text = regex_replace(text, CREDITS_EN, "")
    local credits = CREDITS_BY_LANG[lang]
    if credits then text = regex_replace(text, credits, "") end

    -- 4. trim (string_trim collapses nothing but the edges, as in the copies)
    if type(string_trim) == "function" then
        return string_trim(text)
    end
    return trim(text)
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["urls"] = function(...)
-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
